// Checks the icon family (src/icons/family.ts, generated by scripts/icons/build.py) against what the site needs.
// Run: pnpm test. If one fails after a drawing change, run `python3 scripts/icons/build.py` and read its output.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { glyphs, aliases, legacySolid, categoryGlyphs, config } from '../../src/icons/family.ts';
import { icons } from '../../src/components/ui/icons.ts';

const names = Object.keys(glyphs);
const categories = JSON.parse(readFileSync(new URL('../../content/categories.json', import.meta.url), 'utf8')) as { id: string }[];

test('every glyph has a Solid and a Line drawing on the 20 grid', () => {
  assert.equal(config.grid, 20);
  for (const [name, g] of Object.entries(glyphs)) {
    assert.ok(g.solid.length > 0 && g.line.length > 0, `${name} needs both drawings`);
    assert.ok(!/<svg/.test(g.solid + g.line), `${name}: inner markup only, the renderer adds the svg`);
  }
});

test('every old icon name still resolves to a glyph', () => {
  for (const old of Object.keys(icons)) {
    const target = old in glyphs ? old : (aliases as Record<string, string>)[old];
    assert.ok(target && names.includes(target), `old name ${old} has no glyph`);
  }
  for (const t of [...Object.values(aliases), ...Object.values(legacySolid)]) assert.ok(names.includes(t), `alias target ${t} missing`);
});

test('every category and collectible layer has a glyph', () => {
  for (const c of categories) assert.ok(names.includes((categoryGlyphs as Record<string, string>)[c.id]), `category ${c.id} has no glyph`);
});

test('masks use the per-instance id token, and nothing has an em or en dash', () => {
  for (const [name, g] of Object.entries(glyphs)) {
    for (const m of [g.solid, g.line]) {
      if (m.includes('<mask')) assert.ok(m.includes('id="%ID%"') && m.includes('url(#%ID%)'), `${name}: mask without the id token`);
      assert.ok(!/[\u2013\u2014]/.test(m + g.label), `${name}: dash`);
    }
  }
});
